import {escapeHTML as e} from './roster-view.js';
import {thresholdProgress} from './progress.js';
export const BUILD_LABEL='Scroll 0.6.1 · warm-green-1';
const fact=v=>`<span class="${v==='not yet quantified'?'muted':''}">${e(v)}</span>`;
export function attributesView(attributes){return `<section class="card"><h2>Attributes</h2><div class="ref-grid character-attributes">${attributes.map(a=>`<div class="attribute"><span>${e(a.label)}</span><strong>${e(a.value)}</strong><span>${e(a.note||'')}</span></div>`).join('')}</div></section>`;}
export function vitalsView(c,definitions=[],levels={}){const next=levels[String(c.level+1)];return `<section class="card vitals"><h2>Vitals</h2><div class="resources">${c.resources.map(r=>`<div class="resource"><span>${e(r.label||definitions.find(d=>d.id===r.id)?.label||r.id)}</span><div class="big-number">${r.current} <span>/ ${r.max}</span></div><progress aria-label="${e(r.label||definitions.find(d=>d.id===r.id)?.label||r.id)}" max="${Math.max(1,r.max)}" value="${Math.min(r.max,Math.max(0,r.current))}"></progress>${r.current>r.max?'<p class="over-max">Current exceeds maximum</p>':''}</div>`).join('')}</div><div class="stats-row"><div>Level<strong class="stat-value">${c.level}</strong></div><div>XP<strong class="stat-value">${c.xp_total}</strong>${typeof next==='number'?`<progress aria-label="XP toward next level" max="${Math.max(1,next)}" value="${Math.min(c.xp_total,next)}"></progress><p>${Math.max(0,next-c.xp_total)} to level ${c.level+1}</p>`:'<p>Next threshold not set</p>'}</div></div></section>`;}
export function abilitiesView(slots,thresholds=[]){let empty=[];const groups=[];const flush=()=>{if(empty.length){groups.push(`<p class="empty-slots muted">${empty.length===1?'Slot':'Slots'} ${empty.map(s=>e(s.index)).join(', ')} · Open${empty.some(s=>s.name)?' · '+empty.filter(s=>s.name).map(s=>e(s.name)).join(' / '):''}</p>`);empty=[];}};for(const slot of slots){if(!slot.applications?.length){empty.push(slot);continue;}flush();groups.push(`<section class="ability-slot"><h3>${e(slot.name||'Slot '+slot.index)}</h3><div class="actions"><button data-expand-group="open">Expand all</button><button data-expand-group="close">Collapse all</button></div>${slot.applications.map((a,i)=>{if(typeof a==='string')return `<p>${e(a)} · Status needs explicit confirmation</p>`;const t=thresholds.find(t=>t.id===a.threshold_id);return `<details class="ability ability-display" data-ui-detail="ability-${slot.index}-${i}"><summary><span class="ability-name">${e(a.name)}</span><span class="status ${e(a.status)}">${e(({locked:'✓ Locked',trained_unquantified:'≈ Trained · not yet quantified',in_development:'◷ In development',not_recorded:'? Status not recorded'})[a.status]||a.status)}</span><span class="ability-preview"><span class="ability-facts"><span><b>Cost</b>${fact(a.cost)}</span><span><b>Range</b>${fact(a.range)}</span></span><span class="effect-preview">${fact(a.effect)}</span><span class="more-cue">More ▾</span></span>${a.status==='in_development'&&t?`<span class="inline-progress">${thresholdStatus(t)}</span>`:''}<span class="collapse-cue">Less ▴</span></summary><dl>${['cost','range','effect','notes'].map(k=>`<dt>${k[0].toUpperCase()+k.slice(1)}</dt><dd>${fact(a[k])}</dd>`).join('')}</dl></details>`;}).join('')}</section>`);}flush();return `<section class="card"><h2>Abilities</h2>${groups.join('')||'<p>No ability slots recorded.</p>'}</section>`;}
export function thresholdStatus(t){const p=thresholdProgress(t);return p.complete?'Complete':`In progress ${p.current_stage_index+1} of ${t.stages.length}`;}
export function thresholdsView(thresholds,slots=[]){const groups=new Map();for(const t of thresholds){const linked=slots.flatMap(s=>s.applications||[]).find(a=>typeof a==='object'&&a.threshold_id===t.id);const group=linked?.name||'Other training';if(!groups.has(group))groups.set(group,[]);groups.get(group).push(t);}return `<section class="card"><h2>Training thresholds</h2>${[...groups].map(([name,items])=>`<h3>${e(name)}</h3>${items.map(t=>{const p=thresholdProgress(t);return `<details class="threshold ${p.complete?'is-complete':''}" data-ui-detail="threshold-${e(t.id)}"><summary>${e(t.label===t.id?'Training threshold':t.label)} <span class="status">${thresholdStatus(t)}</span></summary>${t.stages.map((g,i)=>{const v=p.stages[i];return `<p>Stage ${i+1} · DC ${e(g.dc_revisions.at(-1)?.dc??'not set')} · ${e(g.consecutive_required?v.streak:v.successes)}/${g.required} ${g.consecutive_required?'consecutive successes':'successes'}${v.complete?' ✓':''}</p>`;}).join('')}<details class="technical"><summary>Technical details</summary><p>threshold_id: ${e(t.id)}</p>${t.stages.map(g=>`<p>stage_index: ${g.stage_index} · dc_revision_id: ${e(g.dc_revisions.at(-1)?.revision_id||'not set')}</p>`).join('')}</details>${p.complete?'<details><summary>Manage</summary>':''}<button data-action="threshold-dc" data-threshold="${e(t.id)}">Set / amend DC</button>${p.complete?'</details>':''}</details>`;}).join('')}`).join('')||'<p>No training thresholds recorded.</p>'}</section>`;}
// Expansion is local UI state only, scoped by caller to campaign/owner or snapshot owner.
export function bindDisplay(root,scope){const key='scroll-display:'+scope;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}');}catch{}for(const d of root.querySelectorAll('[data-ui-detail]')){d.open=saved[d.dataset.uiDetail]===true;const summary=d.querySelector?.(':scope > summary');if(summary&&d.matches('.ability-display,.move-display'))summary.addEventListener('click',event=>{if(event.target.closest('button,a,input,select,textarea,[contenteditable="true"]'))return;event.preventDefault();d.open=!d.open;});d.addEventListener('toggle',()=>{saved[d.dataset.uiDetail]=d.open;try{localStorage.setItem(key,JSON.stringify(saved));}catch{}});}for(const b of root.querySelectorAll('[data-expand-group]'))b.onclick=()=>{for(const d of b.closest('.ability-slot').querySelectorAll('details'))d.open=b.dataset.expandGroup==='open';};}
